def solve(grid):
    """
    Reconstructs the original periodic pattern of the grid.
    The input may contain zeroes that indicate missing entries.
    The output is the complete grid where each cell matches the underlying pattern.
    """
    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # ---------- find rows and columns that contain no zeros ----------
    full_rows = [i for i in range(rows) if all(v != 0 for v in grid[i])]
    full_cols = [j for j in range(cols) if all(grid[i][j] != 0 for i in range(rows))]

    # ---------- find vertical period (py) ----------
    py = rows  # default: no vertical repetition
    for period in range(1, rows):
        ok = True
        for i in full_rows:
            if i + period < rows:
                if grid[i] != grid[i + period]:
                    ok = False
                    break
        if ok:
            py = period
            break

    # ---------- find horizontal period (px) ----------
    px = cols  # default: no horizontal repetition
    for period in range(1, cols):
        ok = True
        for j in full_cols:
            if j + period < cols:
                col1 = [grid[i][j] for i in range(rows)]
                col2 = [grid[i][j + period] for i in range(rows)]
                if col1 != col2:
                    ok = False
                    break
        if ok:
            px = period
            break

    # ---------- build the pattern (py x px) ----------
    pattern = [[None] * px for _ in range(py)]
    for i in range(rows):
        for j in range(cols):
            val = grid[i][j]
            if val != 0:
                imod = i % py
                jmod = j % px
                if pattern[imod][jmod] is None:
                    pattern[imod][jmod] = val
                # (if already set we assume consistency)

    # In the rare case some pattern cell stayed unknown, fill it with any
    # known value from the same row or column – this cannot happen for the
    # given puzzles but we keep it robust.
    for imod in range(py):
        for jmod in range(px):
            if pattern[imod][jmod] is None:
                # try to copy from another column with same row modulo
                for j2 in range(cols):
                    if pattern[imod][j2 % px] is not None:
                        pattern[imod][jmod] = pattern[imod][j2 % px]
                        break
                # if still None, try row
                if pattern[imod][jmod] is None:
                    for i2 in range(rows):
                        if pattern[i2 % py][jmod] is not None:
                            pattern[imod][jmod] = pattern[i2 % py][jmod]
                            break

    # ---------- reconstruct the whole grid ----------
    result = [[pattern[i % py][j % px] for j in range(cols)] for i in range(rows)]
    return result

